package order

import "errors" // stdlib logic only; NO database/sql, NO net/http

type Order struct {
	ID    int
	Total int // cents
}

func (o Order) Validate() error {
	if o.Total <= 0 {
		return errors.New("total must be positive")
	}
	return nil
}

package order

// Port: the interface the use case needs.
type Repository interface {
	Save(o Order) error
}

type Service struct{ repo Repository } // depends on the abstract port

func NewService(r Repository) *Service { return &Service{repo: r} }

func (s *Service) Place(o Order) error {
	if err := o.Validate(); err != nil {
		return err
	}
	return s.repo.Save(o) // an injected adapter does the real work
}

