package main

import (
	"errors"
	"fmt"
)

// --- Entity (innermost layer): pure domain type, no infrastructure ---
type Order struct {
	ID    int
	Total int // cents
}

// --- Port: the interface the use case NEEDS, defined by the consumer ---
type OrderRepository interface {
	Save(o Order) error
	ByID(id int) (Order, error)
}

// --- Use case (service): depends only on the port, never a concrete store ---
type OrderService struct {
	repo OrderRepository // injected dependency (the abstract port)
}

func NewOrderService(r OrderRepository) *OrderService {
	return &OrderService{repo: r} // accept the interface, return a struct
}

func (s *OrderService) Place(id, total int) error {
	if total <= 0 {
		return errors.New("order total must be positive") // a business rule
	}
	return s.repo.Save(Order{ID: id, Total: total})
}

// --- Adapter (outer layer): an in-memory implementation of the port ---
type memRepo struct{ data map[int]Order }

func newMemRepo() *memRepo { return &memRepo{data: map[int]Order{}} }

func (m *memRepo) Save(o Order) error { m.data[o.ID] = o; return nil }
func (m *memRepo) ByID(id int) (Order, error) {
	o, ok := m.data[id]
	if !ok {
		return Order{}, errors.New("not found")
	}
	return o, nil
}

// --- Composition root: wire the concrete adapter into the service ---
func main() {
	svc := NewOrderService(newMemRepo()) // inject the in-memory adapter
	if err := svc.Place(1, 4200); err != nil {
		fmt.Println("error:", err)
		return
	}
	if err := svc.Place(2, -5); err != nil {
		fmt.Println("rejected:", err) // business rule fires
	}
	fmt.Println("order 1 placed for 4200 cents")
}

