package solution

import "errors"

// Balances is the port the Service needs, defined where it is consumed.
type Balances interface {
	Add(id string, amount int) error
	Get(id string) int
}

type Service struct {
	store Balances // depend on the abstraction, not a concrete store
}

func NewService(b Balances) *Service {
	return &Service{store: b} // accept the interface, return a struct
}

// Deposit enforces the business rule, then delegates persistence to the port.
func (s *Service) Deposit(id string, amount int) error {
	if amount <= 0 {
		return errors.New("deposit must be positive") // domain rule
	}
	return s.store.Add(id, amount)
}

func (s *Service) Balance(id string) int {
	return s.store.Get(id)
}

codeLab.testHarness:
package solution

import "testing"

// fakeBalances is an in-memory adapter implementing the Balances port.
type fakeBalances struct{ m map[string]int }

func (f *fakeBalances) Add(id string, amount int) error {
	if f.m == nil {
		f.m = map[string]int{}
	}
	f.m[id] += amount
	return nil
}
func (f *fakeBalances) Get(id string) int { return f.m[id] }

func TestDeposit(t *testing.T) {
	svc := NewService(&fakeBalances{}) // inject the fake — no database

	if err := svc.Deposit("a", 100); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if err := svc.Deposit("a", 50); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got := svc.Balance("a"); got != 150 {
		t.Errorf("balance = %d, want 150", got)
	}
	if err := svc.Deposit("a", 0); err == nil {
		t.Error("expected error for non-positive deposit, got nil")
	}
	if got := svc.Balance("a"); got != 150 {
		t.Errorf("balance changed after rejected deposit: %d, want 150", got)
	}
}

