// ---- package postgres (infrastructure / outer layer) ----
package postgres

import (
	"database/sql"

	"myapp/internal/order" // imports INWARD toward the domain -> allowed
)

// Repo is the ADAPTER; it satisfies order.Repository structurally.
type Repo struct{ db *sql.DB }

func New(db *sql.DB) *Repo { return &Repo{db: db} }

func (r *Repo) Save(o order.Order) error {
	_, err := r.db.Exec("INSERT INTO orders(id, total) VALUES ($1, $2)", o.ID, o.Total)
	return err
}

// ---- package main (composition root): the only place that knows both ----
package main

import (
	"database/sql"

	"myapp/internal/order"
	"myapp/internal/storage/postgres"
)

func main() {
	db, _ := sql.Open("postgres", "...dsn...")
	repo := postgres.New(db)          // build the concrete adapter
	svc := order.NewService(repo)     // inject it into the domain service
	_ = svc.Place(order.Order{ID: 1, Total: 4200})
}
